import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"22、【賁】 離下艮上","description":"周易集註 - 22、【賁】 離下艮上","frontmatter":{"title":"22、【賁】 離下艮上","description":"周易集註 - 22、【賁】 離下艮上"},"headers":[],"relativePath":"classics/jizhu/026.md","filePath":"classics/jizhu/026.md"}'),t={name:"classics/jizhu/026.md"};function h(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_22、【賁】-離下艮上" tabindex="-1">22、【賁】 離下艮上 <a class="header-anchor" href="#_22、【賁】-離下艮上" aria-label="Permalink to “22、【賁】 離下艮上”">​</a></h1><p>賁飾也，為卦山下有火，山者百物草木之所聚，下有火，則照見其上，品彙皆被光彩，賁之象也。《序卦》：“嗑者合也，物不可以苟合也，故受之以賁。”所以次噬嗑。</p><p>小利攸往，亦為亨，但亨之不大耳。</p><p>《彖》曰：賁亨，柔來而文剛，故亨。分剛上而文柔，故小利有攸往，天文也;文明以止，人文也。觀乎天文，以察時變;觀乎人文，以化成天下。</p><p>以卦綜、卦德釋卦辭，而極言之。本卦綜噬嗑，柔來文剛者，噬嗑上卦之柔，來文賁之剛也，柔指離之陰卦，剛則艮之陽卦也。柔來文剛，以成離明，內而離明，則足以照物，動罔不臧，所以亨。分者，又分下卦也。分剛上而文柔者，分噬嗑下卦之剛，上而為艮，以文柔也，剛指震之陽卦，柔則離之陰卦也。剛上而文柔，以成艮止，外而艮止，則內而能知之，外而不能行之，僅可小利有攸往而已，不能建大功業也，故以其卦綜觀之，柔來文剛，剛上文柔，是即天之文也，何也?蓋在天成象，日月五星之運行，不過此一剛一柔，一往一來而已，今本卦剛柔交錯，是賁之文，即天之文也，以其卦德觀之，是即人之文也，何也?蓋人之所謂文者，不過文之明也，而燦然有禮以相接，文之止也，而截然有分以相守，今本卦內而離明，外而艮止，是賁之文，即人之文也，觀天文以察時變，觀人文以化成天下，賁之文不其大哉!變者，四時寒暑代謝之變也，化者，變而為新，成者，久而成俗。</p><h3 id="《象》曰-山下有火-賁-君子以明庶政-無敢折獄。" tabindex="-1">《象》曰：山下有火，賁，君子以明庶政，無敢折獄。 <a class="header-anchor" href="#《象》曰-山下有火-賁-君子以明庶政-無敢折獄。" aria-label="Permalink to “《象》曰：山下有火，賁，君子以明庶政，無敢折獄。”">​</a></h3><p>明，離象。無敢，艮象。庶者，眾也。繁庶小事，如錢穀出納之類，折獄則一輕重出入之間，民命之死生所繫，乃大事也，曰“無敢”者，非不折獄也，不敢輕折獄也，再三詳審，而後發之意，此即小利有攸往之理。因內明外止，其取象如此，賁與噬嗑相綜，噬嗑利用獄者，明因雷而動也，賁不敢折獄者，明因艮而止也。</p><p>初九，賁其趾，舍車而徒。(舍音舍)</p><p>賁其趾者，道義以文飾其足趾也，舍者棄也，徒者徒行也，舍車而徒，即賁其趾也，言舍車之榮而徒行，是不以徒行為辱，而自以道義為榮也。中爻震與坎，震，趾之象也;坎，車之象也，變艮，止而又止，舍之象也。初比二而應四，比二則從乎坎車矣，應四則從乎震趾矣，然升乎車者，必在上，方可乘，易中言乘者，皆在上也，言承者，皆在下也，初在下，無乘之理，故有舍坎車而從震趾之象，觀小象乘字可見。</p><p>初九剛德明體，蓋內重外輕，自賁於下而隱者也，故有舍非義之車，而安於徒步之象，佔者得此，當以此自處也。</p><h3 id="《象》曰-舍車而徒-義弗乘也。" tabindex="-1">《象》曰：舍車而徒，義弗乘也。 <a class="header-anchor" href="#《象》曰-舍車而徒-義弗乘也。" aria-label="Permalink to “《象》曰：舍車而徒，義弗乘也。”">​</a></h3><p>初在下，無可乘之理。</p><p>六二，賁其須。</p><p>在頤曰須，在口曰髭，在頰曰髯，須不能以自動，隨頤而動，則須雖美，乃附於頤以為文者也。本卦綜噬嗑，原有頤象，今變陽則中爻為兌口矣，口旁之文，莫如須，故以須象之。</p><p>六二以陰柔居中正，三以陽剛得正，皆無應與，故二附三而動，猶須附頤而動也，故有賁其須之象，佔者附其君子，斯無愧於賁矣。</p><h3 id="《象》曰-賁其須-與上興也。" tabindex="-1">《象》曰：賁其須，與上興也。 <a class="header-anchor" href="#《象》曰-賁其須-與上興也。" aria-label="Permalink to “《象》曰：賁其須，與上興也。”">​</a></h3><p>與者相從也，興者興起也。二陰柔從三陽興起者也。</p><p>九三，賁如濡如，永貞吉。</p><p>如，助語辭。濡，沾濡也。離文自飾，賁如之象也，中爻坎水自潤，濡水之象也。永貞者，長永其貞也，九三本貞，教之以永其貞也，吉者陰終不能陵也。</p><p>九三以一陽居二陰之間，當賁之時，陰本比己，為之左右先後，蓋得其賁而潤澤者也，故有賁如濡如之象，然不可溺於所安也。佔者能守永貞之戒，斯吉矣。</p><h3 id="《象》曰-永貞之吉-終莫之陵也。" tabindex="-1">《象》曰：永貞之吉，終莫之陵也。 <a class="header-anchor" href="#《象》曰-永貞之吉-終莫之陵也。" aria-label="Permalink to “《象》曰：永貞之吉，終莫之陵也。”">​</a></h3><p>陵者侮也，能永其貞，則不陷溺於陰柔之中，有所嚴憚，終莫之陵侮矣。</p><p>六四，賁如皤如，白馬翰如，匪寇婚媾。(皤白波反)</p><p>皤，白也，四變中爻為巽，白之象也。賁如皤如者，言未成其賁而成其皤也，非賁如而又皤如也。中爻震為馵足，為的顙，馵白足，顙白顛，白馬之象也，舊注不知象，故言人白，則馬亦白，無是理矣。翰如者，馬如翰之飛也，中爻坎，坎為亟心之馬，翰如之象也，寇指三，婚媾指初。</p><p>六四與初為正應，蓋相為賁者也，乃為九三所隔，而不得遂，故未成其賁，而成其皤，然四往求於初之心，如飛翰之疾，不以三之隔而遂己也，使非三之寇，則與初成婚媾，而相為賁矣，是以始雖相隔，而終則相親也，即象而佔可知矣，與屯六二同。</p><h3 id="《象》曰-六四-當位-疑也。匪寇婚媾-終無尤也。" tabindex="-1">《象》曰：六四，當位，疑也。匪寇婚媾，終無尤也。 <a class="header-anchor" href="#《象》曰-六四-當位-疑也。匪寇婚媾-終無尤也。" aria-label="Permalink to “《象》曰：六四，當位，疑也。匪寇婚媾，終無尤也。”">​</a></h3><p>以陰居陰，故當位，疑者，疑懼其三之親比也，六四守正，三不能求，故終無過尤。</p><p>六五，賁於丘園，束帛戔戔，吝，終吉。(戔音殘)</p><p>艮為山，丘之象也，故頤卦指上九為丘，渙卦中爻艮，故六四渙其丘。艮為果蓏，又居中爻震木之上，果蓏林木，園之象也，此丘園指上九，上九賁白，貧賤肆志，乃山林高蹈之賢，蠱乃同體之卦，上九不事王侯，隨卦上六錯艮，亦曰西山，則上九乃山林之賢無疑矣。兩疋為束，陰爻兩坼，束之象也。坤為帛，此坤土帛之象也。戔與殘同，傷也，艮錯兌，為毀折，戔之象也。束帛傷戔，即今人之禮緞也。本卦上體下體皆外陽中虛，有禮緞之象，上戔下戔，故曰戔戔，陰吝嗇，故曰吝。</p><p>六五文明以止之主，當賁之時，下無應與，乃上比上九高蹈之賢，故有光賁丘園，束帛以聘之象。然賁道將終，文反於質，故又有戔戔之象，以此為禮，有似於吝，然禮薄意勤，禮賢下士，乃人君可喜之事，佔者得此，吉可知矣。</p><h3 id="《象》曰-六五之吉-有喜也。" tabindex="-1">《象》曰：六五之吉，有喜也。 <a class="header-anchor" href="#《象》曰-六五之吉-有喜也。" aria-label="Permalink to “《象》曰：六五之吉，有喜也。”">​</a></h3><p>艮錯兌為悅，故曰有喜，得上九高賢而文之，豈不喜。</p><p>上九，白賁，無咎。</p><p>賁文也，白質也，故曰白受採，上九居賁之極，物極則反，有色復於無色，所以有白賁之象，文勝而反於質，無咎之道也，故其象佔如此。</p><h3 id="《象》曰-白賁無咎-上得志也。" tabindex="-1">《象》曰：白賁無咎，上得志也。 <a class="header-anchor" href="#《象》曰-白賁無咎-上得志也。" aria-label="Permalink to “《象》曰：白賁無咎，上得志也。”">​</a></h3><p>文勝而反於質，退居山林之地，六五之君，以束帛聘之，豈不得志。此以人事言者也，若以卦綜論之，此文原是噬嗑初爻，剛上文柔，以下居上，所以得志。</p>',36)])])}const m=e(t,[["render",h]]);export{_ as __pageData,m as default};
